    39	  batch(changes: readonly StorageChange[]) {
    40	    if (this.disposed) throw Error('Storage is closed');
    41	    let changed = false;
    42	    for (const change of changes) {
    43	      if ('delete' in change) { if (!this.cache.delete(change.key)) continue; }
    44	      else { if (this.cache.has(change.key) && same(this.cache.get(change.key), change.value)) continue; this.cache.set(change.key, change.value); }
