    33	export function buildDiagramContent(ascii: string, revisionId: string, kind: 'diagram' | 'tree' = 'diagram', version?: DiagramParserVersion): DiagramContent {
    34	  const parserVersion = version ?? (kind === 'tree' ? 'ascii-tree-2' : 'ascii-graph-1');
    35	  if (kind === 'tree' && parserVersion !== 'ascii-tree-1' && parserVersion !== 'ascii-tree-2') throw new Error('Unknown tree parser version');
    36	  if (kind === 'diagram' && parserVersion !== 'ascii-graph-1' && parserVersion !== 'legacy-diagram') throw new Error('Unknown diagram parser version');
    37	  // A blank rectangular diagram reserves editable canvas space (e.g. a generated-diagram placeholder).
    38	  const lines = ascii.split('\n');
    39	  const blankRectangle = kind === 'diagram' && lines.length > 1 && lines[0].length > 0
    40	    && lines.every(line => line.length === lines[0].length && /^ +$/.test(line));
    41	  if ((!ascii.trim() && !blankRectangle) || ascii.length > 20000 || /[^\x20-\x7e\n]/.test(ascii)) throw new Error('Diagram must contain 1–20000 printable ASCII characters with LF newlines');
