    43	    structure: parserVersion === 'ascii-graph-1' ? { kind: 'diagram', parserVersion } : { kind: 'diagram' } };
    44	  if (kind === 'diagram') return content;
    45	  const treeVersion = parserVersion as 'ascii-tree-1' | 'ascii-tree-2';
    46	  const parsed = parseAsciiTree(ascii, treeVersion);
    47	  const ids = new Map(parsed.map(node => [node.line, `${revisionId}:${content.asciiSha256}:line-${node.line}`]));
    48	  const nodes: Record<string, DiagramContentNode> = {};
    49	  for (const node of parsed) {
    50	    const id = ids.get(node.line)!;
    51	    const peer = parsed.find(next => next.line > node.line && next.branchColumn <= node.branchColumn);
    52	    nodes[id] = { id, label: node.text, line: node.line, branchColumn: node.branchColumn, startColumn: node.textColumn,
    53	      endColumn: node.textColumn + Math.max(1, node.text.length) - 1,
    54	      parentId: node.parentLine === undefined ? undefined : ids.get(node.parentLine),
    55	      childIds: parsed.filter(child => child.parentLine === node.line).map(child => ids.get(child.line)!),
    56	      foldRanges: node.descendantLines.length ? [{ startLine: node.line + 1, endLine: peer ? peer.line - 1 : ascii.split('\n').length }] : [] };
